import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { getTheme } from '../utils/theme';
import { DUMMY_COLLEGES } from '../data/dummyData';
import { Icons } from '../utils/icons';
import SearchBar from '../components/common/SearchBar';

export default function Colleges() {
  const { setSelectedCollege, setPage, dark, resources } = useApp();
  const css = getTheme(dark);
  const [search, setSearch] = useState('');

  const filtered = DUMMY_COLLEGES.filter(
    (c) =>
      c.name.toLowerCase().includes(search.toLowerCase()) ||
      c.short.toLowerCase().includes(search.toLowerCase()) ||
      c.city.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="fade-in">
      <div style={{ marginBottom: 28 }}>
        <h1 style={{ fontSize: 26, fontWeight: 800 }}>
          Select Your College
        </h1>
      </div>

      <div style={{ marginBottom: 28 }}>
        <SearchBar
          value={search}
          onChange={setSearch}
          placeholder="Search colleges..."
        />
      </div>

      {filtered.map((c) => {
        // ✅ FIXED HERE
        const resCount = resources.filter(
          (r) => r.college === c._id || r.college?._id === c._id
        ).length;

        return (
          <div
            key={c._id || c.id}   // ✅ FIXED
            onClick={() => {
              setSelectedCollege(c);
              setPage('resources');
            }}
            style={{
              ...css.card,
              marginBottom: 10,
              padding: 16,
              cursor: 'pointer',
            }}
          >
            <h3>{c.name}</h3>

            <p>{c.city}</p>

            <p>
              📚 {resCount} resources
            </p>
          </div>
        );
      })}
    </div>
  );
}
